package com.tripcraft.service;
import com.lowagie.text.*; import com.lowagie.text.pdf.PdfWriter; import org.springframework.stereotype.Service; import java.io.ByteArrayOutputStream; import java.util.Map;
@Service public class InvoiceService { private final BookingService bookings; public InvoiceService(BookingService bookings){this.bookings=bookings;} public byte[] generate(long id){Map<String,Object>b=bookings.booking(id); try(ByteArrayOutputStream out=new ByteArrayOutputStream()){Document doc=new Document();PdfWriter.getInstance(doc,out);doc.open();doc.add(new Paragraph("TRIPCRAFT",FontFactory.getFont(FontFactory.HELVETICA_BOLD,20)));doc.add(new Paragraph("Booking invoice #"+b.get("booking_code")));doc.add(new Paragraph(String.valueOf(b.get("title"))+" · "+b.get("destinationName")));doc.add(Chunk.NEWLINE);doc.add(new Paragraph("Travelers: "+b.get("total_people")));doc.add(new Paragraph("Travel date: "+b.get("travel_date")));doc.add(Chunk.NEWLINE);doc.add(new Paragraph("Places: "+b.get("places")));doc.add(new Paragraph("Rooms: "+b.get("rooms")));doc.add(new Paragraph("Vehicles: "+b.get("vehicles")));doc.add(Chunk.NEWLINE);doc.add(new Paragraph("Total: INR "+b.get("total_amount"),FontFactory.getFont(FontFactory.HELVETICA_BOLD,14)));doc.close();return out.toByteArray();}catch(Exception e){throw new IllegalStateException("Could not create invoice",e);} } }
